return ['domain'=>'zinn-reseller','plural-forms'=>'nplurals=1; plural=0;','language'=>'zh_CN','project-id-version'=>'zinn-reseller','pot-creation-date'=>'2026-10-01T08:25:56+00:00','po-revision-date'=>'2026-10-01T08:25:56+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Reseller Toolkit'=>'Zinn® Reseller Toolkit','https://zinndigital.com/wordpress-plugins/zinn-reseller'=>'https://zinndigital.com/wordpress-plugins/zinn-reseller','Sell Zinn Digital® hosting from your own WordPress site — WordPress, WooCommerce, agency, reseller, cloud and VPS hosting. Search and offer domains from your reseller account, sign your clients straight into their hosting panel, and provision hosting automatically when a WooCommerce order is paid.'=>'在您自己的 WordPress 网站上销售 Zinn Digital® 主机服务——包括 WordPress、WooCommerce、代理商、分销商、云主机和 VPS 主机。通过您的分销商账户搜索并提供域名，让您的客户直接登录其主机控制面板，并在 WooCommerce 订单支付成功后自动开通主机。','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','The hosting platform answered with status %d.'=>'托管平台返回的状态码为 %d。','Find your domain name'=>'查找您的域名','Search'=>'搜索','No extensions were checked for that name.'=>'未对该名称检查任何扩展程序。','Domain search is unavailable on this site at the moment.'=>'目前此网站无法进行域名搜索。','We could not reach the domain registry just now. Please try again in a moment.'=>'我们暂时无法连接到域名注册局。请稍后再试。','The API key is missing or no longer valid. Check it under Zinn Digital® → Reseller Toolkit.'=>'API 密钥缺失或已失效。请在 Zinn Digital® → Reseller Toolkit 中进行检查。','This API key does not carry the sites.view permission, which the domain search needs. Add it to the key in your reseller panel, or clear the key here to fall back to the public search.'=>'此 API 密钥不具备域搜索所需的 sites.view 权限。请在您的分销商面板中将其添加到密钥中，或者在此处清除密钥以退回使用公共搜索。','Only administrators see this:'=>'仅限管理员可见：','We could not check this one — try again'=>'我们无法检查此项 — 请重试','Already registered'=>'已注册','Available — ask us for a price'=>'可售——请向我们咨询价格','Avai